-- Dev/staging seed data, generated from a real "Animals in Care" export
-- (Animals_In_Care.xlsx). Safe to re-run: upserts on external_id.
-- Not meant for production -- superseded by real data uploaded through
-- the admin panel's Upload new data flow.

on conflict (external_id) do update set
  name = excluded.name, animal_status = excluded.animal_status, species = excluded.species, location_status = excluded.location_status, admission_type = excluded.admission_type, intake_date = excluded.intake_date, groups = excluded.groups, heartworm_status = excluded.heartworm_status, gender = excluded.gender, altered = excluded.altered, altered_before_arrival = excluded.altered_before_arrival, altered_in_care = excluded.altered_in_care, litter_name = excluded.litter_name, birthday = excluded.birthday, estimated_age = excluded.estimated_age, age_group = excluded.age_group, size_group = excluded.size_group, breed = excluded.breed, secondary_breed = excluded.secondary_breed, eye_color = excluded.eye_color, coat_type = excluded.coat_type, intake_note = excluded.intake_note, partner_type = excluded.partner_type, tags = excluded.tags,
  updated_at = now();
